inline ::flatbuffers::Offset<IRM> CreateIRM(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> JOB_ID = 0,
    uint64_t SEQUENCE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PROVIDER_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> INGESTOR_ID = 0,
    ::flatbuffers::Offset<IRMSource> SOURCE = 0,
    irmJobState STATE = irmJobState_UNSPECIFIED,
    irmRangeMode RANGE_MODE = irmRangeMode_UNSPECIFIED,
    uint64_t NEXT_OFFSET = 0,
    uint32_t NEXT_CHUNK_INDEX = 0,
    uint64_t CHUNK_BYTE_BUDGET = 0,
    ::flatbuffers::Offset<IRMDecodeContext> DECODE_CONTEXT = 0,
    ::flatbuffers::Offset<IRMChunk> LAST_CHUNK = 0,
    uint32_t CHUNKS_COMMITTED = 0,
    uint64_t BYTES_COMMITTED = 0,
    uint64_t RECORDS_COMMITTED = 0,
    ::flatbuffers::Offset<::flatbuffers::String> TARGET_STANDARD = 0,
    ::flatbuffers::Offset<::flatbuffers::String> RECONCILE_MODE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> MERGE_POLICY = 0,
    ::flatbuffers::Offset<IRMFault> FAULT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> CREATED_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> STARTED_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> UPDATED_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> COMPLETED_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::String> EXPIRES_AT = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<::flatbuffers::String>>> TAGS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> NOTES = 0) {
  IRMBuilder builder_(_fbb);
  builder_.add_RECORDS_COMMITTED(RECORDS_COMMITTED);
  builder_.add_BYTES_COMMITTED(BYTES_COMMITTED);
  builder_.add_CHUNK_BYTE_BUDGET(CHUNK_BYTE_BUDGET);
  builder_.add_NEXT_OFFSET(NEXT_OFFSET);
  builder_.add_SEQUENCE(SEQUENCE);
  builder_.add_NOTES(NOTES);
  builder_.add_TAGS(TAGS);
  builder_.add_EXPIRES_AT(EXPIRES_AT);
  builder_.add_COMPLETED_AT(COMPLETED_AT);
  builder_.add_UPDATED_AT(UPDATED_AT);
  builder_.add_STARTED_AT(STARTED_AT);
  builder_.add_CREATED_AT(CREATED_AT);
  builder_.add_FAULT(FAULT);
  builder_.add_MERGE_POLICY(MERGE_POLICY);
  builder_.add_RECONCILE_MODE(RECONCILE_MODE);
  builder_.add_TARGET_STANDARD(TARGET_STANDARD);
  builder_.add_CHUNKS_COMMITTED(CHUNKS_COMMITTED);
  builder_.add_LAST_CHUNK(LAST_CHUNK);
  builder_.add_DECODE_CONTEXT(DECODE_CONTEXT);
  builder_.add_NEXT_CHUNK_INDEX(NEXT_CHUNK_INDEX);
  builder_.add_SOURCE(SOURCE);
  builder_.add_INGESTOR_ID(INGESTOR_ID);
  builder_.add_PROVIDER_ID(PROVIDER_ID);
  builder_.add_JOB_ID(JOB_ID);
  builder_.add_RANGE_MODE(RANGE_MODE);
  builder_.add_STATE(STATE);
  return builder_.Finish();
}

inline ::flatbuffers::Offset<IRM> CreateIRMDirect(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    const char *JOB_ID = nullptr,
    uint64_t SEQUENCE = 0,
    const char *PROVIDER_ID = nullptr,
    const char *INGESTOR_ID = nullptr,
    ::flatbuffers::Offset<IRMSource> SOURCE = 0,
    irmJobState STATE = irmJobState_UNSPECIFIED,
    irmRangeMode RANGE_MODE = irmRangeMode_UNSPECIFIED,
    uint64_t NEXT_OFFSET = 0,
    uint32_t NEXT_CHUNK_INDEX = 0,
    uint64_t CHUNK_BYTE_BUDGET = 0,
    ::flatbuffers::Offset<IRMDecodeContext> DECODE_CONTEXT = 0,
    ::flatbuffers::Offset<IRMChunk> LAST_CHUNK = 0,
    uint32_t CHUNKS_COMMITTED = 0,
    uint64_t BYTES_COMMITTED = 0,
    uint64_t RECORDS_COMMITTED = 0,
    const char *TARGET_STANDARD = nullptr,
    const char *RECONCILE_MODE = nullptr,
    const char *MERGE_POLICY = nullptr,
    ::flatbuffers::Offset<IRMFault> FAULT = 0,
    const char *CREATED_AT = nullptr,
    const char *STARTED_AT = nullptr,
    const char *UPDATED_AT = nullptr,
    const char *COMPLETED_AT = nullptr,
    const char *EXPIRES_AT = nullptr,
    const std::vector<::flatbuffers::Offset<::flatbuffers::String>> *TAGS = nullptr,
    const char *NOTES = nullptr) {
  auto JOB_ID__ = JOB_ID ? _fbb.CreateString(JOB_ID) : 0;
  auto PROVIDER_ID__ = PROVIDER_ID ? _fbb.CreateString(PROVIDER_ID) : 0;
  auto INGESTOR_ID__ = INGESTOR_ID ? _fbb.CreateString(INGESTOR_ID) : 0;
  auto TARGET_STANDARD__ = TARGET_STANDARD ? _fbb.CreateString(TARGET_STANDARD) : 0;
  auto RECONCILE_MODE__ = RECONCILE_MODE ? _fbb.CreateString(RECONCILE_MODE) : 0;
  auto MERGE_POLICY__ = MERGE_POLICY ? _fbb.CreateString(MERGE_POLICY) : 0;
  auto CREATED_AT__ = CREATED_AT ? _fbb.CreateString(CREATED_AT) : 0;
  auto STARTED_AT__ = STARTED_AT ? _fbb.CreateString(STARTED_AT) : 0;
  auto UPDATED_AT__ = UPDATED_AT ? _fbb.CreateString(UPDATED_AT) : 0;
  auto COMPLETED_AT__ = COMPLETED_AT ? _fbb.CreateString(COMPLETED_AT) : 0;
  auto EXPIRES_AT__ = EXPIRES_AT ? _fbb.CreateString(EXPIRES_AT) : 0;
  auto TAGS__ = TAGS ? _fbb.CreateVector<::flatbuffers::Offset<::flatbuffers::String>>(*TAGS) : 0;
  auto NOTES__ = NOTES ? _fbb.CreateString(NOTES) : 0;
  return CreateIRM(
      _fbb,
      JOB_ID__,
      SEQUENCE,
      PROVIDER_ID__,
      INGESTOR_ID__,
      SOURCE,
      STATE,
      RANGE_MODE,
      NEXT_OFFSET,
      NEXT_CHUNK_INDEX,
      CHUNK_BYTE_BUDGET,
      DECODE_CONTEXT,
      LAST_CHUNK,
      CHUNKS_COMMITTED,
      BYTES_COMMITTED,
      RECORDS_COMMITTED,
      TARGET_STANDARD__,
      RECONCILE_MODE__,
      MERGE_POLICY__,
      FAULT,
      CREATED_AT__,
      STARTED_AT__,
      UPDATED_AT__,
      COMPLETED_AT__,
      EXPIRES_AT__,
      TAGS__,
      NOTES__);
}

inline const IRM *GetIRM(const void *buf) {
  return ::flatbuffers::GetRoot<IRM>(buf);
}

inline const IRM *GetSizePrefixedIRM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<IRM>(buf);
}

inline const char *IRMIdentifier() {
  return "$IRM";
}

inline bool IRMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, IRMIdentifier());
}

inline bool SizePrefixedIRMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, IRMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyIRMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<IRM>(IRMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedIRMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<IRM>(IRMIdentifier());
}

inline void FinishIRMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<IRM> root) {
  fbb.Finish(root, IRMIdentifier());
}

inline void FinishSizePrefixedIRMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<IRM> root) {
  fbb.FinishSizePrefixed(root, IRMIdentifier());
}

#endif  // FLATBUFFERS_GENERATED_MAIN_H_
